import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('starts follower term 0', async () => {
  const h = await create();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0 });
});

test('election flow', async () => {
  const h = await create();
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, false);
  assert.ok((await h.electionTimeout()).ok);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1 });
  assert.ok((await h.electionTimeout()).ok);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 2 });
  assert.ok((await h.electionWon()).ok);
  assert.deepEqual(await h.node(), { role: 'leader', term: 2 });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.ok((await h.quorumLost()).ok);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2 });
  assert.ok((await h.electionTimeout()).ok);
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 3 });
});

test('newer term', async () => {
  const h = await create();
  for (const t of [0, 4, -1, 1.5, NaN]) assert.equal((await h.newerTermSeen(t)).ok, false);
  assert.ok((await h.newerTermSeen(2)).ok);
  assert.equal((await h.newerTermSeen(2)).ok, false);
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2 });
});

test('shutdown', async () => {
  const h = await create();
  await h.electionTimeout();
  assert.ok((await h.shutdown()).ok);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1 });
  for (const r of [await h.shutdown(), await h.electionTimeout(), await h.electionWon(), await h.newerTermSeen(3), await h.quorumLost()])
    assert.equal(r.ok, false);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1 });
});

