import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('starts follower term 0', async () => {
  const h = await create();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
});

test('election flow', async () => {
  const h = await create();
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, false);
  assert.ok((await h.electionTimeout()).ok);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1, votedFor: 'itself' });
  assert.ok((await h.electionTimeout()).ok);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 2, votedFor: 'itself' });
  assert.ok((await h.electionWon()).ok);
  assert.deepEqual(await h.node(), { role: 'leader', term: 2, votedFor: 'itself' });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.ok((await h.quorumLost()).ok);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'itself' });
  assert.equal((await h.voteRequested('n1', 2)).ok, false);
  assert.ok((await h.electionTimeout()).ok);
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 3, votedFor: 'itself' });
});

test('newer term', async () => {
  const h = await create();
  for (const t of [0, 4, -1, 1.5, NaN]) assert.equal((await h.newerTermSeen(t)).ok, false);
  await h.electionTimeout();
  assert.ok((await h.newerTermSeen(2)).ok);
  assert.equal((await h.newerTermSeen(2)).ok, false);
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'nobody' });
});

test('votes', async () => {
  const h = await create();
  for (const [c, t] of [['n3', 1], ['itself', 1], ['n1', 0], ['n1', 4], ['n1', 1.5]] as const)
    assert.equal((await h.voteRequested(c, t)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
  assert.ok((await h.voteRequested('n1', 1)).ok);
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'n1' });
  assert.ok((await h.voteRequested('n1', 1)).ok);
  assert.equal((await h.voteRequested('n2', 1)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'n1' });
  // same term, not yet voted
  assert.ok((await h.newerTermSeen(2)).ok);
  assert.ok((await h.voteRequested('n2', 2)).ok);
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  // candidate/leader in same term refuse, newer term steps down
  const g = await create();
  await g.electionTimeout();
  assert.equal((await g.voteRequested('n1', 1)).ok, false);
  await g.electionWon();
  assert.equal((await g.voteRequested('n1', 1)).ok, false);
  assert.ok((await g.voteRequested('n2', 2)).ok);
  assert.deepEqual(await g.node(), { role: 'follower', term: 2, votedFor: 'n2' });
});

test('shutdown', async () => {
  const h = await create();
  await h.electionTimeout();
  assert.ok((await h.shutdown()).ok);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1, votedFor: 'itself' });
  for (const r of [await h.shutdown(), await h.electionTimeout(), await h.electionWon(), await h.newerTermSeen(3), await h.quorumLost(), await h.voteRequested('n1', 3)])
    assert.equal(r.ok, false);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1, votedFor: 'itself' });
});

